  const minAll=all.reduce((a,w)=>a+(w.minutes||0),0);let lootAll={},xp=0;const byDay={};for(const w of all){lootAll=walkLootAdd(lootAll,w.loot);xp+=walkXpOf(w);const d=byDay[w.walked_on]||(byDay[w.walked_on]={n:0,min:0,loot:0});d.n++;d.min+=w.minutes||0;d.loot+=walkLootCount(w.loot)}
