  const B=0.05,by=Math.floor(lat/B),bx=Math.floor(lng/B),gy=lat/B-by,gx=lng/B-bx,bks=new Set([by+'_'+bx]);if(gy<.15)bks.add((by-1)+'_'+bx);if(gy>.85)bks.add((by+1)+'_'+bx);if(gx<.15)bks.add(by+'_'+(bx-1));if(gx>.85)bks.add(by+'_'+(bx+1));
