  {const td=todayStr();if(!WKL.oldMk)WKL.oldMk=wkMarks(WKL.petId).filter(x=>x[2]!==td);WKL.mkSeen=WKL.mkSeen||{};const ms=WKL.mkSeen;if(Object.keys(ms).length<5)for(const x of WKL.oldMk){const kk=x[0]+','+x[1];if(ms[kk])continue;if(walkDist(cur,x)<=25){ms[kk]=1;const g=wkGive([Math.random()<.5?'bone':'ball']);WKL.mkBack=g[0]||'bone';wkSS('mb');break}}}
