  if(WKL.run&&!WKL.run.done){const ps=WKL.pts,n=ps.length;if(now-WKL.run.t>60000){WKL.run.done=1;WKL.runMsg='fail'}else if(n>2){let j=n-1;while(j>0&&now-ps[j-1][2]<=15000)j--;let dd=0;for(let i=j+1;i<n;i++)dd+=walkDist(ps[i-1],ps[i]);const tt=(now-ps[j][2])/1000,v=tt>0?dd/tt:0;if(tt>=12&&v>1.8&&v<3.5&&ps[j][2]>=WKL.run.t-2000){WKL.run.done=1;WKL.runMsg='ok'}}}
