  if(WKL.rest&&!WKL.rest.ok){if(walkDist(WKL.rest.p,cur)>20)WKL.rest=null,WKL.restMsg='走開了，休息中斷';else if(now-WKL.rest.t>=60000){WKL.rest.ok=1;WKL.restMsg='ok'}}
