  if((c>=51&&c<=67)||(c>=80&&c<=82))return `外面在下雨，路滑慢慢走，回家記得把${N}的腳擦乾。`;
  if(t!==null&&t>=32)return `現在 ${Math.round(t)}°C，地面很燙。出門前用手背貼地 5 秒，太燙就改傍晚再走，記得帶水。`;
